# The constants socket defines, read off ruby, in the order
# ext/socket/mkconstants.rb lists them: that order decides which name a
# number several names share is shown by.
#
#   ruby tools/socket.rb path/to/ext/socket/mkconstants.rb > rt/ext/socket/constants.rb
require "socket"

listed = File.read(ARGV.fetch(0)).split(/^__END__\n/).last.each_line.filter_map do |line|
  name = line.split.first
  name.to_sym unless name.nil? || name.start_with?("#")
end
names = listed.uniq.select { |name| Socket::Constants.const_defined?(name, false) }

puts <<~HEAD
  # Generated by tools/socket.rb from ruby's own socket, in the order
  # ext/socket/mkconstants.rb lists the names. Do not edit.
  class Socket < BasicSocket
    module Constants
HEAD
names.each { |name| puts "    #{name} = #{Socket::Constants.const_get(name)}" }
puts "  end"
puts
puts "  # Every name above, in that order."
puts "  def self.constant_names"
puts "    Primitive.attr! :hidden"
puts "    %i["
names.each_slice(8) { |slice| puts "      #{slice.join(" ")}" }
puts "    ]"
puts "  end"
puts "end"
